export const filmCoverLogoUrl=`${import.meta.env.BASE_URL}card-back-logo.svg`;
export const filmCoverCss='.book-page[data-cover] .book-content{padding-top:6mm;height:79mm;font-family:"Courier Prime",monospace;font-size:36pt;font-weight:700}.book-page[data-cover] .book-content.book-cover-bottom{position:absolute;top:210mm;left:20mm;width:170mm;height:64mm;padding-top:0;z-index:2}.book-page>img.book-cover-logo{position:absolute;left:50%;top:50%;bottom:auto;transform:translate(-50%,-50%);width:90mm;height:90mm;max-height:none;max-width:none;object-fit:contain;filter:drop-shadow(0 0 0.35mm rgba(0,0,0,.9)) drop-shadow(0 0.6mm 0.7mm rgba(0,0,0,.65));pointer-events:none;z-index:1}';
export async function filmCoverLogoPng(){const image=new Image();image.src=filmCoverLogoUrl;await image.decode();const canvas=document.createElement('canvas');canvas.width=1033;canvas.height=1033;const context=canvas.getContext('2d')!;context.filter='drop-shadow(0 0 4px rgba(0,0,0,.9)) drop-shadow(0 7px 8px rgba(0,0,0,.65))';context.drawImage(image,0,0,1033,1033);return canvas.toDataURL('image/png');}
